<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';msp2RequireAccess();$error=null;$rows=[];$tot=[];
$q=msp2NormalizeText((string)($_GET['q']??''));$alerta=strtoupper(trim((string)($_GET['alerta']??'')));$estado=strtoupper(trim((string)($_GET['estado']??'')));$permitidas=['','OK','SIN_MONTO','NO_RECIBIDA','RECEPCION_PARCIAL','RECEPCION_EXCEDIDA','SALDO_RESERVADO','INCONSISTENCIA_SALDO'];if(!in_array($alerta,$permitidas,true))$alerta='';$estados=['','NO_RECIBIDA','PARCIAL','COMPLETA','EXCEDIDA'];if(!in_array($estado,$estados,true))$estado='';
$conditions=['1=1'];$params=[];if($q!==''){$conditions[]="(nombre_locatario LIKE :q OR rut LIKE :q OR nombre_comercial LIKE :q OR cdo_local LIKE :q OR CAST(id_contrato_arriendo AS NVARCHAR(20)) LIKE :q)";$params[':q']='%'.$q.'%';}if($alerta!==''){$conditions[]='alerta_codigo=:alerta';$params[':alerta']=$alerta;}if($estado!==''){$conditions[]='estado_recepcion=:estado';$params[':estado']=$estado;}$where=implode(' AND ',$conditions);
function grMonto(mixed $v):string{return '$ '.number_format((float)$v,2,',','.');}
try{$stmt=$conn->prepare("SELECT COUNT(*) registros,SUM(monto_pactado) pactado,SUM(monto_recibido) recibido,SUM(monto_pendiente_recepcion) pendiente,SUM(monto_disponible) disponible,SUM(monto_reservado) reservado,SUM(monto_aplicado) aplicado,SUM(monto_devuelto) devuelto,SUM(CASE WHEN alerta_nivel>0 THEN 1 ELSE 0 END) alertas FROM dbo.msp_vw_garantias_control_integral WHERE $where");$stmt->execute($params);$tot=$stmt->fetch()?:[];$stmt=$conn->prepare("SELECT * FROM dbo.msp_vw_garantias_control_integral WHERE $where ORDER BY alerta_nivel DESC,nombre_locatario,cdo_local,id_garantia");$stmt->execute($params);$rows=$stmt->fetchAll()?:[];}catch(Throwable $e){$error='No fue posible cargar el reporte integral de garantías.';}
$queryExport=http_build_query(array_filter(['q'=>$q,'alerta'=>$alerta,'estado'=>$estado],fn($v)=>$v!==''));
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Control de garantías | MSP</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css"><link rel="stylesheet" href="/portalgp/styles.css"><style>.metric{min-width:150px}</style></head><body class="gp-layout bg-light"><?php include dirname(__DIR__,2).'/templates/header.php';?><main class="gp-main container-fluid py-4 px-lg-4 msp-guarantees-report"><div class="d-flex flex-wrap justify-content-between gap-2 mb-3"><div><p class="text-muted mb-1">MSP / Reportes</p><h1 class="h3">Control integral de garantías</h1><p class="text-muted mb-0">Monto pactado, recepción, disponibilidad, reservas, aplicaciones y devoluciones.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-dark btn-sm" href="<?php echo msp2Escape(msp2Url('garantias/index.php'));?>"><i class="bi bi-arrow-left me-1"></i>Volver a Garantías</a><a class="btn btn-success btn-sm" href="<?php echo msp2Escape(msp2Url('garantias/exportar_reporte.php'.($queryExport!==''?'?'.$queryExport:'')));?>"><i class="bi bi-file-earmark-spreadsheet me-1"></i>Exportar CSV</a></div></div><?php if($error):?><div class="alert alert-danger"><?php echo msp2Escape($error);?></div><?php endif;?>
<form method="get" class="card card-body mb-3"><div class="row g-2 align-items-end"><div class="col-lg-5"><label class="form-label">Buscar</label><input name="q" value="<?php echo msp2Escape($q);?>" class="form-control" placeholder="Arrendatario, RUT, tienda, contrato o local"></div><div class="col-lg-3"><label class="form-label">Alerta</label><select name="alerta" class="form-select"><option value="">Todas</option><?php foreach(array_slice($permitidas,1) as $a):?><option value="<?php echo $a;?>" <?php echo $alerta===$a?'selected':'';?>><?php echo msp2Escape(str_replace('_',' ',$a));?></option><?php endforeach;?></select></div><div class="col-lg-2"><label class="form-label">Recepción</label><select name="estado" class="form-select"><option value="">Todas</option><?php foreach(array_slice($estados,1) as $e):?><option value="<?php echo $e;?>" <?php echo $estado===$e?'selected':'';?>><?php echo msp2Escape(str_replace('_',' ',$e));?></option><?php endforeach;?></select></div><div class="col-lg-2 d-grid"><button class="btn btn-primary">Filtrar</button></div></div></form>
<div class="d-flex flex-wrap gap-2 mb-3"><?php foreach(['Pactado'=>'pactado','Recibido'=>'recibido','Pendiente recepción'=>'pendiente','Disponible'=>'disponible','Reservado'=>'reservado','Aplicado'=>'aplicado','Devuelto'=>'devuelto'] as $label=>$key):?><div class="card metric flex-fill"><div class="card-body py-2"><div class="small text-muted"><?php echo msp2Escape($label);?></div><div class="fw-bold"><?php echo msp2Escape(grMonto($tot[$key]??0));?></div></div></div><?php endforeach;?><div class="card metric border-warning flex-fill"><div class="card-body py-2"><div class="small text-muted">Alertas</div><div class="fw-bold text-warning-emphasis"><?php echo (int)($tot['alertas']??0);?> / <?php echo (int)($tot['registros']??0);?></div></div></div></div>
<div class="msp-guarantees-table-wrap"><table class="table table-hover table-sm align-middle mb-0 msp-guarantees-table"><thead class="table-light"><tr><th>Arrendatario / local</th><th>Contrato</th><th class="text-end">Pactado</th><th class="text-end">Recibido</th><th class="text-end">Pendiente</th><th class="text-end">Disponible</th><th class="text-end">Reservado</th><th class="text-end">Aplicado</th><th class="text-end">Devuelto</th><th>Alerta</th><th class="text-center">Acciones</th></tr></thead><tbody><?php if($rows===[]):?><tr><td colspan="11" class="text-center text-muted py-4">Sin resultados.</td></tr><?php endif;foreach($rows as $r):$level=(int)$r['alerta_nivel'];$badge=$level>=3?'danger':($level===2?'warning':($level===1?'secondary':'success'));?><tr><td><div class="fw-semibold cell-ellipsis" title="<?php echo msp2Escape((string)$r['nombre_locatario']);?>"><?php echo msp2Escape((string)$r['nombre_locatario']);?></div><div class="small text-muted cell-ellipsis" title="<?php echo msp2Escape((string)$r['rut']);?> · Local <?php echo msp2Escape((string)$r['cdo_local']);?>"><?php echo msp2Escape((string)$r['rut']);?> · Local <?php echo msp2Escape((string)$r['cdo_local']);?></div></td><td><span class="fw-semibold"><?php echo (int)$r['id_contrato_arriendo'];?></span><div class="small text-muted">G. <?php echo (int)$r['id_garantia'];?></div></td><?php foreach(['monto_pactado','monto_recibido','monto_pendiente_recepcion','monto_disponible','monto_reservado','monto_aplicado','monto_devuelto'] as $key):?><td class="text-end money" title="<?php echo msp2Escape(grMonto($r[$key]));?>"><?php echo msp2Escape(grMonto($r[$key]));?></td><?php endforeach;?><td><span class="badge text-bg-<?php echo $badge;?> cell-ellipsis" title="<?php echo msp2Escape(str_replace('_',' ',(string)$r['alerta_codigo']));?>"><?php echo msp2Escape(str_replace('_',' ',(string)$r['alerta_codigo']));?></span><div class="small text-muted mt-1 cell-ellipsis" title="<?php echo msp2Escape((string)$r['alerta_descripcion']);?>"><?php echo msp2Escape((string)$r['alerta_descripcion']);?></div></td><td><div class="msp-guarantees-actions"><a class="btn btn-outline-success btn-sm" href="<?php echo msp2Escape(msp2Url('garantias/recepciones.php'));?>" title="Recepciones" aria-label="Recepciones"><i class="bi bi-box-arrow-in-down"></i></a><a class="btn btn-outline-danger btn-sm" href="<?php echo msp2Escape(msp2Url('garantias/devoluciones.php'));?>" title="Devoluciones" aria-label="Devoluciones"><i class="bi bi-box-arrow-up"></i></a><a class="btn btn-outline-secondary btn-sm" href="<?php echo msp2Escape(msp2Url('contratos/ficha.php?id_contrato_arriendo='.(int)$r['id_contrato_arriendo']));?>" title="Ficha del contrato" aria-label="Ficha del contrato"><i class="bi bi-file-earmark-text"></i></a></div></td></tr><?php endforeach;?></tbody></table></div></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script></body></html>
